class Solution {
    fun maxValue(n:String,x:Int):String{
        var index=if(n[0]=='-')1 else 0;
        if(n[0]=='-')while(index<n.length&&n[index]-'0'<=x)index++ else while(index<n.length&&n[index]-'0'>=x)index++;
        return n.substring(0,index)+x+n.substring(index)
    }
}

code.cpp:
class Solution {
    public: string maxValue(string n,int x){
        int index=n[0]=='-'?1:0;
        if(n[0]=='-')while(index<(int)n.size()&&n[index]-'0'<=x)++index;
        else while(index<(int)n.size()&&n[index]-'0'>=x)++index;
        return n.substr(0,index)+char('0'+x)+n.substr(index);
    }
};
